    const D = m.dk, sl = { hdr: 0, qt: (c) => 1 + c, qp: 1 + V, kt: (c) => 2 + V + c, kp: (i) => 2 + 2 * V + i };
    key = region(at, D, 2 + 2 * V + T, sl);
